#include <iostream>
#include <vector>

int majorityElement(std::vector<int>& arr) {
    int n = arr.size();
    int candidate = -1;
    int count = 0;

    // Find a candidate
    for (int num : arr) {
        if (count == 0) {
            candidate = num;
            count = 1;
        } else if (num == candidate) {
            count++;
        } else {
            count--;
        }
    }

    // Validate the candidate
    int valid_count = 0;
    for (int num : arr) {
        if (num == candidate) {
            valid_count++;
        }
    }

    // If count is greater than n / 2, return the candidate; otherwise, return -1
    if (valid_count > n / 2) {
        return candidate;
    } else {
        return -1;
    }
}

int main() {
    std::vector<int> arr = {1, 1, 2, 1, 3, 5, 1};
    std::cout << majorityElement(arr) << std::endl;
    return 0;
}
